import numpy as np

# the values of IQ4_XS, by the four bits of a weight (kvalues_iq4nl)
IQ4NL = np.array([-127, -104, -83, -65, -49, -35, -22, -10, 1, 13, 25, 38, 53, 69, 89, 113], dtype=np.int8)

# what a digit of a grid stands for
LEVELS = {"IQ2XXS": (8, 25, 43), "IQ2XS": (8, 25, 43), "IQ2S": (8, 25, 43),
          "IQ3XXS": (4, 12, 20, 28, 36, 44, 52, 62), "IQ3S": (1, 3, 5, 7, 9, 11, 13, 15), "IQ1S": (-1, 0, 1)}
# how many values an entry of a grid holds
GROUP = {"IQ2XXS": 8, "IQ2XS": 8, "IQ2S": 8, "IQ3XXS": 4, "IQ3S": 4, "IQ1S": 8}


def grid(name):
    """The grid called name as (entries, the values of an entry) of int8: IQ2XXS 256 x 8, IQ2XS 512 x 8, IQ2S 1024 x 8,
    IQ3XXS 256 x 4, IQ3S 512 x 4, and IQ1S 2048 x 8, which IQ1_M reads as well."""
    digits = np.frombuffer(DIGITS[name].encode(), dtype=np.uint8) - np.uint8(48)
    return np.array(LEVELS[name], dtype=np.int8)[digits].reshape(-1, GROUP[name])


